---
export async function executeMultiModelReview(
  item: ReviewItem,
  systemPrompt: string,
  userPrompt: string,
  config: BridgebuilderConfig,
  adapters: PipelineAdapters,
  enrichment?: EnrichmentContext,
): Promise<MultiModelReviewResult> {
  const multiConfig = config.multiModel!;
  const { poster, sanitizer, logger } = adapters;

  // Validate API keys (cycle-127 FR-1: and the agy opt-in, read from the repo's Loa config)
  const keyStatus = validateApiKeys(multiConfig, readAgyGate(config.repoRoot ? path.join(config.repoRoot, ".loa.config.yaml") : ".loa.config.yaml"));
  for (const np of keyStatus.notPlanned) {
    logger.info(`${np.provider} voice not planned: agy opt-in off (hounfour.headless.agy_opt_in)`);
  }
  if (multiConfig.api_key_mode === "strict" && keyStatus.missing.length > 0) {
    throw new Error(
      `Strict mode: missing API keys for providers: ${keyStatus.missing.map((m) => m.provider).join(", ")}`,
    );
  }

  // Create adapters for available providers
  const modelAdapters: Array<{
    provider: string;
    modelId: string;
    adapter: ILLMProvider;
  }> = [];

  for (const entry of keyStatus.valid) {
    const envVar = PROVIDER_API_KEY_ENV[entry.provider];
    // (a headless entry is valid without a key — validateApiKeys — and cheval's CLI hop never reads one)
    const apiKey = (envVar ? process.env[envVar] : undefined) ?? "";
    if (!apiKey && !isHeadlessModelId(entry.modelId, entry.provider)) continue;

    const costRates = multiConfig.cost_rates?.[entry.provider];
    const adapter = createAdapter({
      provider: entry.provider,
      modelId: entry.modelId,
      apiKey,
      timeoutMs: deriveTimeoutMs(entry.provider, entry.modelId, config),
---

  const combinedContent = modelResults
    .filter((r) => r.response)
    .map((r) => r.response!.content)
    .join("\n\n---\n\n");
  const findings = findingsPerModel.flatMap((result) => result.findings);
  let reviewVerdict = summarizeReviewVerdict(combinedContent, findings);
  // Enrichment may surface a blocker; it cannot approve unparsed reviews.
  if (summarizeReviewVerdict(consensusBody).verdict === "REQUEST_CHANGES") {
    reviewVerdict = summarizeReviewVerdict(combinedContent + "\n" + consensusBody, findings);
  }
  // Incomplete or degraded participation can never clear a merge.
  if (modelResults.length !== multiConfig.models.length - keyStatus.notPlanned.length ||
      modelResults.some((result) => result.error || !result.response) ||
      computeVerdictBand(modelResults.map((result) => ({ verdictQuality: result.response?.verdictQuality }))) !== "APPROVED") {
    reviewVerdict.mergeBlocked = true;
  }

  return {
    modelResults,
    consensus,
    posted: overallPosted || modelResults.some((r) => r.posted),
    combinedContent,
    reviewVerdict,
    notPlanned: keyStatus.notPlanned,
  };
}

